/* Levels are tints of the accent over a neutral empty square, so the grid follows the selected accent and both themes. */
.root { --level-0: color-mix(in oklch, var(--foreground) 6.5%, var(--surface)); --level-1: color-mix(in oklch, var(--accent) 26%, var(--level-0)); --level-2: color-mix(in oklch, var(--accent) 50%, var(--level-0)); --level-3: color-mix(in oklch, var(--accent) 76%, var(--level-0)); --level-4: var(--accent); container-type: inline-size; position: relative; display: grid; min-width: 0; gap: var(--space-4); color: var(--foreground); }
.header { display: flex; min-width: 0; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: var(--space-3) var(--space-4); }
.summary { display: flex; min-width: 0; flex-wrap: wrap; align-items: baseline; column-gap: .3em; margin: 0; color: var(--text-secondary); font-size: var(--text-sm); line-height: var(--leading-body); font-variant-numeric: tabular-nums; }
.total { color: var(--foreground); font-weight: 500; white-space: nowrap; }
.period { white-space: nowrap; }
.actions { display: flex; flex: none; align-items: center; }
.rollingFrame { display: inline-flex; justify-content: flex-end; overflow: clip; overflow-clip-margin: .2em; }
.rolling { display: inline-flex; flex: none; }
/* Each place is its own window, so a turning digit clips at the line instead of brushing the next line of text. */
.place { position: relative; display: inline-flex; overflow: clip; overflow-clip-margin: .15em; }
.placeChar, .riseLine { display: inline-block; }
.rise { position: relative; display: inline-flex; }

/* The scroller starts at its right edge on narrow screens (the most recent weeks) without script, through its writing direction. */
.scroller { direction: rtl; overflow-x: auto; overflow-y: hidden; margin: -6px; padding: 6px; overscroll-behavior-x: contain; scrollbar-color: var(--border-strong) transparent; scrollbar-width: thin; }
.canvas { --gap: 3px; --label: 30px; --cell: clamp(9px, calc((100cqi - var(--label) - var(--gap) * 53) / 53), 15px); --step: calc(var(--cell) + var(--gap)); direction: ltr; display: grid; width: max-content; grid-template-columns: var(--label) auto; grid-template-rows: auto auto; column-gap: var(--gap); row-gap: var(--space-2); }
.months { position: relative; grid-row: 1; grid-column: 2; height: 1rem; color: var(--text-muted); font-size: var(--text-xs); line-height: 1rem; }
/* Month labels glide to their new week when a range starts on a different weekday. */
.month { position: absolute; top: 0; left: 0; white-space: nowrap; transform: translateX(calc(var(--col) * var(--step))); transition: transform var(--duration-spring) var(--ease-spring); }
/* Weekday labels stay pinned while a narrow grid scrolls under them. Set --heatmap-surface when the heatmap sits on another surface. */
.weekdays { position: sticky; z-index: 1; left: -6px; display: grid; grid-row: 1 / 3; grid-column: 1; grid-template-rows: repeat(7, var(--cell)); align-content: end; row-gap: var(--gap); margin: 0 calc(var(--gap) * -1) 0 -6px; padding: 0 var(--gap) 0 6px; background: var(--heatmap-surface, var(--surface)); color: var(--text-muted); font-size: var(--text-xs); }
.weekday { display: flex; height: var(--cell); align-items: center; white-space: nowrap; line-height: 1; }
.plot { position: relative; grid-row: 2; grid-column: 2; }
.grid { display: grid; gap: var(--gap); outline: none; }
.row { display: flex; gap: var(--gap); }

/* One square per day. The wave delay rides a custom property so a reveal and a recolor sweep the same diagonal. */
.cell { --delay: var(--wave); display: block; width: var(--cell); height: var(--cell); flex: none; border-radius: calc(var(--cell) * .28); background: var(--level-0); outline: 1.5px solid transparent; outline-offset: 1px; cursor: default; -webkit-tap-highlight-color: transparent; transition: background-color 320ms var(--ease-standard) var(--delay), transform var(--duration-spring) var(--ease-spring) var(--delay), opacity var(--duration-fast) var(--ease-standard); }
.grid[data-direction="back"] .cell { --delay: var(--wave-back); }
.cell[data-level="1"] { background: var(--level-1); }
.cell[data-level="2"] { background: var(--level-2); }
.cell[data-level="3"] { background: var(--level-3); }
.cell[data-level="4"] { background: var(--level-4); }
/* Days outside the range shrink away in the sweep and grow back when a range needs them. */
.cell[data-empty] { transform: scale(0); background: var(--level-0); }
.grid[data-reveal="hidden"] .cell { opacity: 0; transform: scale(.5); transition: none; }
.grid[data-reveal="hidden"] .cell[data-empty] { transform: scale(0); }
.grid[data-reveal="revealing"] .cell { transition: background-color 320ms var(--ease-standard) var(--delay), transform var(--duration-spring) var(--ease-spring) var(--delay), opacity 360ms var(--ease-enter) var(--delay); }
.grid[data-highlight] .cell:not([data-empty]) { opacity: .2; }
.grid[data-highlight="0"] .cell[data-level="0"], .grid[data-highlight="1"] .cell[data-level="1"], .grid[data-highlight="2"] .cell[data-level="2"], .grid[data-highlight="3"] .cell[data-level="3"], .grid[data-highlight="4"] .cell[data-level="4"] { opacity: 1; }
@media (hover: hover) and (pointer: fine) { .cell:not([data-empty]):hover { outline-color: color-mix(in oklch, var(--foreground) 45%, transparent); } }
.cell:focus-visible { outline: 2px solid var(--focus-ring); outline-offset: 2px; }
.cell[aria-selected="true"]:focus-visible { outline-color: transparent; }

/* The selection ring glides between days, and follows its day when the range changes. */
.ring { position: absolute; top: -3px; left: -3px; width: calc(var(--cell) + 6px); height: calc(var(--cell) + 6px); border: 1.5px solid var(--foreground); border-radius: calc(var(--cell) * .28 + 3px); opacity: 0; pointer-events: none; transform: translate(calc(var(--col) * var(--step)), calc(var(--row) * var(--step))); transition: transform var(--duration-spring) var(--ease-spring), opacity var(--duration-fast) var(--ease-standard); }
.ring[data-shown] { opacity: 1; }

.legend { display: flex; min-width: 0; align-items: center; justify-content: space-between; gap: var(--space-3); color: var(--text-muted); font-size: var(--text-xs); }
/* The caption names the previewed level; it sits apart from the scale so its changing width never nudges the swatches. */
.caption { position: relative; min-width: 0; overflow: hidden; color: var(--text-secondary); font-variant-numeric: tabular-nums; white-space: nowrap; text-overflow: ellipsis; }
.scale { display: flex; flex: none; align-items: center; gap: var(--space-2); }
.captionShort { display: none; }
/* Narrow cards keep the day count and let the highlighted squares say which level it is. */
@container (max-width: 440px) { .captionLong { display: none; } .captionShort { display: inline; } }
.legendText { line-height: 1; }
.swatches { display: flex; }
/* The visible square stays the size of a day while the button keeps a comfortable target around it. */
.swatch { position: relative; display: grid; width: 15px; height: 20px; place-items: center; padding: 0; border: 0; border-radius: 4px; background: transparent; cursor: pointer; -webkit-tap-highlight-color: transparent; }
.swatch::before { content: ""; width: 11px; height: 11px; border-radius: 3px; background: var(--level-0); }
.swatch[data-level="1"]::before { background: var(--level-1); }
.swatch[data-level="2"]::before { background: var(--level-2); }
.swatch[data-level="3"]::before { background: var(--level-3); }
.swatch[data-level="4"]::before { background: var(--level-4); }
.swatch[aria-pressed="true"] { box-shadow: inset 0 0 0 1.5px var(--foreground); }
.swatch:focus-visible { outline: 2px solid var(--focus-ring); outline-offset: 1px; }

/* One bubble for the whole grid. The outer layer glides between cells; the bubble fades and scales from its tail. */
.tip { position: absolute; z-index: 5; top: 0; left: 0; width: 0; height: 0; pointer-events: none; }
.bubble { position: absolute; bottom: 8px; left: 0; display: block; padding: 7px 12px 8px; border: 1px solid color-mix(in oklch, var(--background) 14%, var(--foreground)); border-radius: var(--radius-control); background: var(--foreground); color: var(--background); box-shadow: var(--shadow-raised); transform-origin: 50% 100%; will-change: transform, opacity; }
.tipBody { position: relative; display: block; overflow: clip; overflow-clip-margin: 8px; }
.tipMeasure { position: absolute; top: 0; left: 0; display: grid; width: max-content; visibility: hidden; }
.tipLines { display: grid; width: max-content; }
.tipMeasure > span, .tipLines > span { white-space: nowrap; }
.tipPrimary { font-size: var(--text-sm); font-weight: 500; line-height: 1.3; font-variant-numeric: tabular-nums; }
.tipSecondary { color: color-mix(in oklch, var(--background) 68%, var(--foreground)); font-size: var(--text-xs); line-height: 1.35; }

.srOnly { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

@media (prefers-reduced-motion: reduce) {
  .cell, .grid[data-reveal="revealing"] .cell { transition: background-color 150ms linear, opacity 150ms linear; }
  .grid[data-reveal="hidden"] .cell { transform: none; }
  .cell[data-empty], .grid[data-reveal="hidden"] .cell[data-empty] { opacity: 0; transform: none; }
  .month, .ring { transition: opacity 150ms linear; }
}

/* Vue SFC alias */
.container { composes: root; }
.info { composes: summary; }
.label { font-weight: 500; font-size: var(--text-sm); }
.gridWrap { composes: scroller; }
.footer { composes: legend; }
.legendCells { composes: swatches; }
.level0 { background: var(--surface-muted); }
.level1 { background: color-mix(in oklch, var(--accent) 25%, var(--surface-muted)); }
.level2 { background: color-mix(in oklch, var(--accent) 50%, var(--surface-muted)); }
.level3 { background: color-mix(in oklch, var(--accent) 75%, var(--surface-muted)); }
.level4 { background: var(--accent); }
